import type { Preview } from '@storybook/react-vite';

const preview: Preview = {
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
    a11y: {
      test: 'todo',
    },
  },
};

export default preview;

{
  "compilerOptions": {
    "tsBuildInfoFile": "./node_modules/.tmp/tsconfig.app.tsbuildinfo",

    // Emission
    "noEmit": true, // Do not emit by default (only type check)
    //"emitDeclarationOnly": false,
    "target": "ESNext", // JavaScript language version to emit
    "module": "ESNext", // The type of file to emit (CommonJS/ESM/etc.)
    "esModuleInterop": false,
    "allowSyntheticDefaultImports": true,

    // Imports
    "moduleResolution": "bundler", // Resolve import specifiers like bundlers (allows explicit file extensions)
    "moduleDetection": "force", // Enforce that we're always using ESM
    "isolatedModules": true, // Restrict language features not compatible with tools like babel
    "allowImportingTsExtensions": true, // Allow importing `.ts` extensions
    "allowJs": true, // If `true` allows to import `.js` files
    "resolveJsonModule": true, // Allow importing `.json` files
    "forceConsistentCasingInFileNames": true, // Do not allow case-insensitive import file name matching
    "paths": {
      //"@": ["./src"],
    },

    // Type checking
    //"typeRoots": [],
    //"types": [], // https://stackoverflow.com/questions/59322550, https://stackoverflow.com/questions/55550096
    "lib": ["ES2024", "DOM", "DOM.Iterable"], // Library declaration files to include (globally)
    "skipLibCheck": true, // Do not type check declaration files (for performance)
    "noErrorTruncation": true,

    // Language
    "strict": true,
    "exactOptionalPropertyTypes": true,
    "noUncheckedIndexedAccess": true,
    "useDefineForClassFields": true, // Use latest ES spec version of class fields
    "jsx": "react-jsx",

    // Linting
    //"noUnusedLocals": true,
    //"noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true,
    "noUncheckedSideEffectImports": true,

    // Check CSS module class names in the IDE
    "plugins": [{
      "name": "typescript-plugin-css-modules",
      "options": {
        //"classnameTransform": "camelCase",
        //"goToDefinition": true,
      },
    }],
  },
  "include": [
    "app",
    "src",
    //"tests/installation", // Don't type check this, will fail in CI due to missing `node_modules`
  ],
  "exclude": [
    "node_modules",
    "**/*.test.ts",
    "**/*.test.tsx",
    "**/*.spec.ts",
    "**/*.spec.tsx",
  ],
}

/// <reference types="vitest/config" />
/// <reference types="vitest" />

import * as path from "node:path";
//import * as url from 'node:url';
//import { glob } from 'tinyglobby';

import browserslist from "browserslist";
import { defineConfig, esmExternalRequirePlugin } from "vite";
import {
  Features as LightningCssFeatures,
  browserslistToTargets,
} from "lightningcss";

// Vite plugins
import dts from "vite-plugin-dts";
import { libInjectCss } from "vite-plugin-lib-inject-css";
import svgr from "vite-plugin-svgr";
import { createSvgIconsPlugin } from "vite-plugin-svg-icons-ng";
import react from "@vitejs/plugin-react";
import { fileURLToPath } from "node:url";
import { storybookTest } from "@storybook/addon-vitest/vitest-plugin";
import { playwright } from "@vitest/browser-playwright";
const dirname =
  typeof __dirname !== "undefined"
    ? __dirname
    : path.dirname(fileURLToPath(import.meta.url));
const playwrightProviderOptions =
  process.env.STORYBOOK_TEST_SCREENSHOTS === "true"
    ? {
        contextOptions: {
          deviceScaleFactor: 2,
          viewport: { width: 393, height: 852 },
          isMobile: true,
          hasTouch: true,
          userAgent:
            "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1",
        },
      }
    : {};

// More info at: https://storybook.js.org/docs/next/writing-tests/integrations/vitest-addon

export default defineConfig({
  root: "./app", // Run with `app` as root, so that files like `index.html` are by default referenced from there
  base: "./", // Assets base URL

  assetsInclude: ["**/*.md"], // Add `.md` as static asset type

  resolve: {
    alias: {
      // Needed for file references in Sass code (relative paths don't resolve properly when imported with `@use`)
      "@": path.resolve(__dirname, "./src"),
    },
  },

  plugins: [
    react(),

    svgr(),

    // Handle SVG sprite icons
    createSvgIconsPlugin({
      iconDirs: [path.resolve(__dirname, "src/assets/icons")],
      symbolId: "baklava-icon-[name]",
      inject: "body-last",
      customDomId: "baklava-icon-sprite",
    }),
    //libInjectCss(), // Disabled for now (`.css` import causes issues in vitest)

    // Generate `.d.ts` files
    dts({
      // https://github.com/qmhc/vite-plugin-dts/issues/275#issuecomment-1963123685
      outDir: "dist", // dts.root + 'dist' => where we need to rollup.
      root: "../", //vite.root + ../ = ./ = (dts.root)
      staticImport: true,
      insertTypesEntry: true,
      //rollupTypes: true, // Issue: https://github.com/qmhc/vite-plugin-dts/issues/399

      //include: [path.resolve(__dirname, 'app')],
      tsconfigPath: path.resolve(__dirname, "tsconfig.app.json"),
    }),
  ],
  css: {
    // Configure preprocessing using Sass
    preprocessorOptions: {
      scss: {},
    },
    // Configure postprocessing using lightningcss
    transformer: "lightningcss",
    lightningcss: {
      targets: browserslistToTargets(
        browserslist(
          `fully supports css-nesting AND fully supports css-cascade-layers`,
        ),
      ),
      exclude: LightningCssFeatures.LightDark, // Do not include the `light-dark()` polyfill (it's too buggy)
      cssModules: {
        //pattern: '[hash]_[local]',
        grid: false, // Workaround for https://github.com/parcel-bundler/lightningcss/issues/762
      },
    },
  },
  // https://dev.to/receter/how-to-create-a-react-component-library-using-vites-library-mode-4lma
  // https://victorlillo.dev/blog/react-typescript-vite-component-library
  build: {
    emptyOutDir: true,
    /*
    rollupOptions: {
      input: {
        baklava: path.resolve(__dirname, 'app/main.tsx'),
      },
    },
    */

    copyPublicDir: false, // Do not copy `./public` into the output dir
    outDir: path.resolve(__dirname, "dist"),
    lib: {
      entry: path.resolve(__dirname, "app/baklava.ts"),
      fileName: (_format, entryName) => `${entryName}.js`,
      //cssFileName: 'baklava',
      formats: ["es"],
    },
    rolldownOptions: {
      // Do not include React in the output (rely on the consumer to bring their own version)
      // external: ['react', 'react/jsx-runtime'],
      plugins: [
        esmExternalRequirePlugin({
          external: ["react", "react/jsx-runtime"],
        }),
      ],
      // input: Object.fromEntries(
      //   glob.sync('src/**/*.{ts,tsx}', {
      //     ignore: ['src/**/*.d.ts'],
      //   }).map(file => [
      //     // The name of the entry point
      //     // lib/nested/foo.ts becomes nested/foo
      //     path.relative(
      //       'src',
      //       file.slice(0, file.length - path.extname(file).length)
      //     ),
      //     // The absolute path to the entry file
      //     // lib/nested/foo.ts becomes /project/lib/nested/foo.ts
      //     url.fileURLToPath(new URL(file, import.meta.url)),
      //   ]),
      // ),
    },
  },
  test: {
    root: ".", // Override the default `root` of `./app`
    environment: "jsdom",
    globals: true,
    setupFiles: ["./tests/setup-rtl.ts"],
    deps: {
      optimizer: {
        web: {
          exclude: [], // Don't exclude externals from bundling in tests
        },
      },
    },
    projects: [
      {
        extends: true,
        test: {
          name: "unit",
          include: ["./src/**/*.test.{ts,tsx}"],
        },
      },
      {
        extends: true,
        plugins: [
          // The plugin will run tests for the stories defined in your Storybook config
          // See options at: https://storybook.js.org/docs/next/writing-tests/integrations/vitest-addon#storybooktest
          storybookTest({
            configDir: path.join(dirname, ".storybook"),
          }),
        ],
        test: {
          name: "storybook",
          browser: {
            enabled: true,
            headless: true,
            provider: playwright(playwrightProviderOptions),
            instances: [
              {
                browser: "chromium",
              },
            ],
          },
        },
      },
    ],
  },
});

