 39→  triggerAction?: undefined | UseFloatingElementOptions['triggerAction'],
 40→  
 41→  /** Where to show the tooltip, relative to the anchor. */
 42→  placement?: undefined | TooltipPlacement,
 43→  
 44→  /** Enable more precise tracking of the anchor, at the cost of performance. Default: `false`. */
 45→  enablePreciseTracking?: undefined | boolean,
 46→  
 47→  /** A custom boundary to use to determine overflow of the tooltip. */
 48→  boundary?: undefined | Element,
 49→  
 50→  /** Callback that is invoked when the tooltip gets activated. */
 51→  onTooltipActivated?: undefined | (() => void),
 52→  
 53→  /** Callback that is invoked when the tooltip gets deactivated. */
 54→  onTooltipDeactivated?: undefined | (() => void),
 55→};
 56→/**
 57→ * Provider around an anchor element to attach a tooltip popover.
 58→ */
 59→export const TooltipProvider = (props: TooltipProviderProps) => {
 60→  const {
 61→    children,
 62→    tooltip,
 63→    triggerAction = 'hover',
 64→    placement,
 65→    size,
 66→    enablePreciseTracking = false,
 67→    boundary,
 68→    onTooltipActivated,
 69→    onTooltipDeactivated,
 70→    ...tooltipProps
 71→  } = props;
 72→  
 73→  const arrowRef = React.useRef<HTMLElement>(null);
 74→  
 75→  const {
 76→    context,
 77→    isMounted,
 78→    isOpen,
 79→    refs,
 80→    floatingStyles,
 81→    getReferenceProps,
 82→    getFloatingProps,
 83→    placement: activePlacement,
 84→  } = useFloatingElement({
 85→    role: 'tooltip',
 86→    triggerAction,
 87→    keyboardInteractions: 'default',
 88→    placement,
 89→    offset: 14,
 90→    enablePreciseTracking,
 91→    boundary,
 92→    ...(arrowRef.current ? { arrowRef: arrowRef as React.RefObject<HTMLElement> } : {}),
 93→  });
 94→  const arrow = useFloatingElementArrow({ context });
 95→  
 96→  // Call event listeners, if any
 97→  // biome-ignore lint/correctness/useExhaustiveDependencies(onTooltipActivated): Only call on state change
 98→  // biome-ignore lint/correctness/useExhaustiveDependencies(onTooltipDeactivated): Only call on state change
 99→  React.useEffect(() => {
100→    if (isMounted) {
101→      onTooltipActivated?.();
102→    } else {
103→      onTooltipDeactivated?.();
104→    }
105→  }, [isMounted]);
106→  
107→  
108→  // Get the `floatingProps` early, because the anchor depends on `floatingProps.id`
109→  const floatingProps = getFloatingProps({
110→    popover: 'manual',
111→    style: floatingStyles,
112→  });
113→  
114→  const renderAnchor = () => {
115→    const renderPropArg: GetReferenceProps = (userProps: React.HTMLProps<Element> = {}) => {
116→      const props = getReferenceProps(userProps);
117→      const ref = mergeRefs(userProps?.ref, refs.setReference, props.ref as undefined | React.Ref<Element>);
118→      
119→      return {
120→        ...props,
121→        ref,
122→        ['aria-describedby']: floatingProps.id,
123→      };
124→    };
125→    
126→    if (typeof children === 'function') {
127→      return children(renderPropArg);
128→    }
129→    
130→    // If a render prop is not used, try to attach it to the element directly.
131→    // NOTE: `cloneElement` is marked as a legacy function by React. Recommended is to use a render prop instead.
132→    if (!React.isValidElement(children)) {
133→      return <span {...renderPropArg()}>{children}</span>;
134→    }
135→    if (React.Children.count(children) === 1) {
136→      return React.cloneElement(children, renderPropArg(children.props as React.HTMLProps<Element>));
137→    }
138→    
139→    console.error(`Invalid children passed to TooltipContainer, expected a render prop or single child element.`);
140→    return children;
141→  };
142→  
143→  // biome-ignore lint/correctness/useExhaustiveDependencies(isOpen): We want to rerender content on open
144→  const tooltipContent = React.useMemo(() => {
145→    return typeof tooltip === 'function' ? tooltip() : tooltip;
146→  }, [tooltip, isOpen]);
147→  
148→  const renderTooltip = () => {
149→    if (!isMounted || !tooltipContent) { return null; }
150→    
151→    const arrowClassName = (() => {
152→      const placement = activePlacement.split('-')[0] as TooltipPlacement;
153→      switch (placement) {
154→        case 'top': return cx(TooltipClassNames['bk-tooltip--arrow'], TooltipClassNames['bk-tooltip--arrow-bottom']);
155→        case 'right': return cx(TooltipClassNames['bk-tooltip--arrow'], TooltipClassNames['bk-tooltip--arrow-left']);
156→        case 'bottom': return cx(TooltipClassNames['bk-tooltip--arrow'], TooltipClassNames['bk-tooltip--arrow-top']);
157→        case 'left': return cx(TooltipClassNames['bk-tooltip--arrow'], TooltipClassNames['bk-tooltip--arrow-right']);
158→        default: return assertUnreachable(placement);
159→      }
160→    })();
161→    
162→    const arrowPos = ((): string | number => {
163→      const placement = activePlacement.split('-')[0] as TooltipPlacement;
164→      
165→      switch (placement) {
166→        case 'top':
167→        case 'bottom':
168→          return arrow?.arrowX ?? '50%';
169→        case 'right':
170→        case 'left':
171→          return arrow?.arrowY ?? '50%';
172→        default:
173→          return assertUnreachable(placement);
174→      }
175→    })();
176→    
177→    return (
178→      <Tooltip
179→        {...mergeProps(floatingProps, tooltipProps)}
180→        ref={mergeRefs<HTMLDivElement>(
181→          refs.setFloating,
182→          floatingProps.ref as React.Ref<HTMLDivElement>,
183→          tooltipProps.ref,
184→        )}
185→        className={cx(
186→          cl['bk-tooltip-provider__tooltip'],
187→          floatingProps.className as ClassNameArgument,
188→          arrowClassName,
189→          tooltipProps.className,
190→        )}
191→        style={{
192→          ...(floatingProps.style ?? {}),
193→          ...tooltipProps.style,
194→          '--arrow-pos': arrowPos,
195→        } as React.CSSProperties}
196→        size={size}
197→      >
198→        {tooltipContent}
199→        {/*
200→        Fake arrow element for position tracking, the real arrow is drawn using `border-image`.
201→        Note: `floating-ui` has a `FloatingArrow` component using a positioned <svg> arrow, but this doesn't work if
202→        the tooltip has `overflow: hidden/scroll/auto` or `contain: paint` enabled.
203→        */}
204→        <span ref={arrowRef} hidden/>
205→      </Tooltip>
206→    );
207→  };
208→  
209→  return (
210→    <>
211→      {renderAnchor()}
212→      
213→      {/* Use a portal to prevent CSS rules from the parent from being inherited into the Tooltip */}
214→      {createPortal(renderTooltip(), document.body)} 
215→    </>
216→  );
217→};
