23→
24→type EventProps = {
25→  event: 'warning',
26→};
27→const Event = (props: EventProps) => {
28→  if (props.event !== 'warning') {
29→    return null;
30→  }
31→  const icon: IconName = props.event === 'warning' ? 'warning-filled' : props.event;
32→  return (
33→    <Icon icon={icon} className={cl[`bk-icon-event--${icon}`]} />
34→  );
35→};
36→
37→export type IconProps = React.PropsWithChildren<ComponentProps<'svg'> & {
38→  /** Whether this component should be unstyled. */
39→  unstyled?: boolean,
40→  
41→  /** The name of the icon to display */
42→  icon: IconName,
43→  
44→  /** The color to apply to the icon */
45→  color?: undefined | string,
46→  
47→  /** Visual decoration to apply */
48→  decoration?: undefined | Decoration,
49→}>;
50→export const Icon = Object.assign(
51→  ({ unstyled, icon, color = 'currentColor', decoration, ...props }: IconProps) => {
52→    const symbolId = `#baklava-icon-${icon}`;
53→    
54→    return (
55→      <svg
56→        role="presentation"
57→        aria-hidden // https://stackoverflow.com/questions/61048356/why-do-we-use-aria-hidden-with-icons
58→        {...props}
59→        className={cx(
60→          'bk',
61→          'icon', // Global class name (for generic targeting in CSS)
62→          { [cl['bk-icon']]: !unstyled },
63→          { [cl['bk-icon--background-circle']]: decoration?.type === 'background-circle' },
64→          props.className,
65→        )}
66→      >
67→        <use href={symbolId} fill={color}/>
68→      </svg>
69→    );
70→  }, {
71→    Event,
72→  },
73→);
