15→export type TextLineProps = ComponentProps<'span'> & {
16→  /** Whether to show a tooltip with the full text content in case of overflow. Default: true. */
17→  showOverflowTooltip?: undefined | boolean,
18→};
19→/**
20→ * A single-line piece of text.
21→ */
22→export const TextLine = (props: TextLineProps) => {
23→  const { showOverflowTooltip = true, ...propsRest } = props;
24→  
25→  const elementRef = React.useRef<null | HTMLSpanElement>(null);
26→  
27→  const renderTooltip = React.useCallback(() => {
28→    const element = elementRef.current;
29→    if (!element) { return; }
30→    
31→    const hasOverflow = element.scrollWidth > element.clientWidth;
32→    return hasOverflow ? (element.innerText ?? null) : null;
33→  }, []);
34→  
35→  const text = (
36→    <span
37→      ref={elementRef}
38→      {...propsRest}
39→      className={cx(
40→        'bk',
41→        cl['bk-text-line'],
42→        propsRest.className,
43→      )}
44→    />
45→  );
46→  
47→  if (showOverflowTooltip) {
48→    return (
49→      <TooltipProvider tooltip={renderTooltip}>
50→        {text}
51→      </TooltipProvider>
52→    );
53→  }
54→  
55→  return text;
