 23→const getFlexValueFromColumn = <D extends object>(col: ReactTable.ColumnInstance<D>) => {
 24→  return (col?.bkColumnWidth?.flex ?? 1); // defaults to 1
 25→};
 26→
 27→const getFlexColumnWidth = <D extends object>(col: ReactTable.ColumnInstance<D>) => {
 28→  return (col?.bkColumnWidth?.width ?? 0);
 29→};
 30→
 31→const isFlexColumn = <D extends object>(col: ReactTable.ColumnInstance<D>) => {
 32→  return (col && Object.hasOwn(col, 'bkColumnWidth'));
 33→};
 34→
 35→const requireNewCol = <D extends object>(col: ReactTable.ColumnInstance<D>) => {
 36→  return (isFlexColumn(col) && (col.bkColumnWidth?.flex ?? 0) > 0);
 37→};
 38→
 39→const calculateFlexPercentage = <D extends object>(
 40→  allColumns: ReactTable.ColumnInstance<D>[],
 41→  targetColumn: ReactTable.ColumnInstance<D>
 42→) => {
 43→  if (!isFlexColumn(targetColumn)) {
 44→    return 0;    
 45→  }
 46→
 47→  const targetColumnFlex = getFlexValueFromColumn(targetColumn);
 48→  const totalFlex = allColumns.reduce((total, column) => total + getFlexValueFromColumn(column), 0);
 49→  
 50→  if (targetColumnFlex === 0) {
 51→    return 0;
 52→  }
 53→  
 54→  return totalFlex > 0 ? Math.round((targetColumnFlex / totalFlex) * 100) : 0;
 55→};
