 57→export const generateCustomColGroup = <D extends object>(
 58→  allColumns: ReactTable.ColumnInstance<D>[],
 59→  columnGroups?: React.ReactNode): React.ReactNode | null => {
 60→  if (columnGroups) {
 61→    return columnGroups;
 62→  } else {
 63→    // Generate a new <colgroup>
 64→    const cols: React.ReactNode[] = [];
 65→
 66→    allColumns.forEach((col) => {
 67→      cols.push(
 68→        <col
 69→          key={`${col.id}-base`}
 70→          style={{
 71→            ...col.style,
 72→            inlineSize: isFlexColumn(col) ? getFlexColumnWidth(col) : col?.style?.width ?? '10ch'
 73→          }}
 74→        />
 75→      );
 76→      if (requireNewCol(col)) {
 77→        //Add extra dummy cols for using colspan
 78→        cols.push(
 79→          <col
 80→            key={`${col.id}-stretch`}
 81→            style={{
 82→              inlineSize: `${calculateFlexPercentage(allColumns, col)}%`
 83→            }}
 84→          />
 85→        );
 86→      }
 87→    });
 88→
 89→    return <colgroup>{cols}</colgroup>;
 90→  }
 91→};
 92→
 93→const getTotalColSpan = <D extends object>(columns: ReactTable.ColumnInstance<D>[]) => {
 94→  return columns.reduce((total, col) => total + (requireNewCol(col) ? 2 : 1), 0);
 95→};
